     6→// The navigation structure is a DAG (Directed Acyclic Graph):
     7→//
     8→//   Nodes = BreadcrumbItemDescriptor (entities with id + routePath)
     9→//   Edges = BreadcrumbEdge (transitions between nodes, carrying injected context)
    10→//
    11→// GLOBAL_ROUTE_DESCRIPTORS are the DAG root nodes.
    12→// Items do NOT carry a "kind" field. To resolve an item's descriptor,
    13→// use the edge index: given a parent descriptor and an item id,
    14→// the edge tells you which descriptor the child resolves to.
    15→//
    16→// The breadcrumb stack is a path through this graph.
    17→
    18→// ── Node (Descriptor) ──
    19→
    20→export interface BreadcrumbItemDescriptor {
    21→  id: string;
    22→  routePath: string;
    23→  icon: IconData;
    24→  titleKey: string;
    25→  fallbackLabel: string;
    26→  isContainer?: boolean;
    27→}
    28→
    29→// ── Edges ──
