   345→
   346→/** Resolve icon for an item by looking up its descriptor */
   347→export function getDescriptorIcon(descriptorId: string | undefined): IconData | undefined {
   348→  if (!descriptorId) return undefined;
   349→  return DESCRIPTOR_BY_ID.get(descriptorId)?.icon;
   350→}
   351→
   352→// ─── Lookup Helpers ──────────────────────────────────────────────────────────
   353→
   354→/** All descriptors in the DAG (roots + children) */
   355→export const ALL_DESCRIPTORS: BreadcrumbItemDescriptor[] = [
   356→  ...GLOBAL_ROUTE_DESCRIPTORS,
   357→  ...WORKSPACE_SECTION_DESCRIPTORS,
   358→  ...SETTINGS_SECTION_DESCRIPTORS,
   359→];
   360→
   361→const DESCRIPTOR_BY_ID = new Map<string, BreadcrumbItemDescriptor>(
   362→  ALL_DESCRIPTORS.map((d) => [d.id, d])
   363→);
   364→
   365→/** Look up a descriptor by id */
   366→export function getDescriptor(id: string): BreadcrumbItemDescriptor | undefined {
   367→  return DESCRIPTOR_BY_ID.get(id);
   368→}
   369→
   370→/** Resolve descriptor for a DesktopLocation */
   371→export function getDescriptorForLocation(location: DesktopLocation): BreadcrumbItemDescriptor | undefined {
   372→  const descriptorId = LOCATION_DESCRIPTOR_MAP[location.kind];
   373→  if (!descriptorId) return undefined;
   374→  // Handle wildcard patterns like "workspace-section:*"
   375→  if (descriptorId.endsWith(":*") && "section" in location) {
   376→    const prefix = descriptorId.slice(0, -1);
   377→    return DESCRIPTOR_BY_ID.get(prefix + (location as { section: string }).section);
   378→  }
   379→  return DESCRIPTOR_BY_ID.get(descriptorId);
   380→}
   381→
   382→export function getGlobalRouteDescriptor(path: string): BreadcrumbItemDescriptor | undefined {
   383→  return GLOBAL_ROUTE_DESCRIPTORS.find((d) => d.routePath === path);
   384→}
