   399→  if (value === "agents") return "agent";
   400→  if (isWorkspaceSection(value)) return value;
   401→  return "chat";
   402→}
   403→
   404→export function getSettingsSectionDescriptor(section?: string): SettingsSectionDescriptor | undefined {
   405→  return SETTINGS_SECTION_DESCRIPTORS.find((item) => item.section === section);
