   412→export function normalizeSettingsSection(value?: string | null): SettingsSection {
   413→  if (!value) return "general";
   414→  return isSettingsSection(value) ? value : "general";
   415→}
   416→
   417→export function getSettingsSectionLabel(section?: string): string {
   418→  const descriptor = getSettingsSectionDescriptor(section);
   419→  if (!descriptor) return i18n.t("settings.title", "Settings");
   420→  return i18n.t(descriptor.titleKey, descriptor.fallbackLabel);
   421→}
