   477→): string {
   478→  const params = new URLSearchParams();
   479→  if (workspacePath) params.set("workspace_path", workspacePath);
   480→  if (extraParams) {
   481→    Object.entries(extraParams).forEach(([key, value]) => {
   482→      if (value) params.set(key, value);
   483→    });
   484→  }
   485→  const query = params.toString();
   486→  return query ? `?${query}` : "";
