   613→    return { kind: "documents" };
   614→  }
   615→  if (url === "/devices/pair") {
   616→    return { kind: "device-pair" };
   617→  }
   618→  if (url.startsWith("/settings")) {
   619→    const section = url.split("/")[2];
   620→    return { kind: "settings", section: normalizeSettingsSection(section) };
   621→  }
   622→
   623→  if (url === "/publish" || url === "/my-packages" || url === "/analytics") {
   624→    return { kind: "global-route", path: url };
   625→  }
   626→
   627→  if (url.startsWith("/workspace/page")) {
   628→    const parsed = new URL(url, "http://desktop.local");
   629→    const workspaceId = parsed.searchParams.get("workspace_id");
   630→    const pagePath = parsed.searchParams.get("page_path");
   631→    return {
   632→      kind: "workspace-page",
   633→      workspaceId: workspaceId ?? "global",
   634→      pageSlug:
   635→        pagePath?.replace(/^pages\//, "").replace(/\/SKILL\.md$/, "") ?? "page",
   636→    };
   637→  }
   638→
   639→  if (url.startsWith("/workspace/")) {
   640→    const parsed = new URL(url, "http://desktop.local");
   641→    const parts = parsed.pathname.split("/").filter(Boolean);
   642→    const workspaceId = parts[1];
   643→    if (!workspaceId) {
   644→      return { kind: "documents" };
   645→    }
   646→
   647→    if (parts.length === 2) {
   648→      return { kind: "workspace-home", workspaceId };
   649→    }
   650→
   651→    if (parts[2] === "apps" && !parts[3]) {
   652→      return { kind: "workspace-apps", workspaceId };
   653→    }
   654→
   655→    if (parts[2] === "page" && parts[3]) {
   656→      return {
   657→        kind: "workspace-page",
   658→        workspaceId,
   659→        pageSlug: parts
   660→          .slice(3)
   661→          .map((part) => decodeURIComponent(part))
   662→          .join("/"),
   663→      };
   664→    }
   665→
   666→    if (parts[2] === "agent" && parts[3]) {
   667→      return {
   668→        kind: "workspace-agent-detail",
   669→        workspaceId,
   670→        agentId: decodeURIComponent(parts[3]),
   671→      };
   672→    }
   673→
   674→    if (parts[2] === "executor" && parts[3]) {
   675→      return {
   676→        kind: "workspace-executor-detail",
   677→        workspaceId,
   678→        executorType: decodeURIComponent(parts[3]),
   679→      };
   680→    }
   681→
   682→    if (parts[2] === "web") {
   683→      return {
   684→        kind: "workspace-web",
   685→        workspaceId,
   686→        url: parsed.searchParams.get("url") ?? "",
   687→        title: parsed.searchParams.get("title") ?? "Web",
   688→        sourcePageSlug: parsed.searchParams.get("source_page") ?? undefined,
   689→        webId: parsed.searchParams.get("web_id") ?? undefined,
   690→      };
   691→    }
   692→
   693→    return {
   694→      kind: "workspace-section",
   695→      workspaceId,
   696→      section: normalizeWorkspaceSection(parts[2] ?? "chat"),
   697→    };
   698→  }
   699→
   700→  return { kind: "global-route", path: url };
   701→}
